void str_gbk2utf8(char *gbk, char *utf8)
{
    gbk_union_t gbk_val;
    utf8_union_t utf8_val;

    uint16_t i;
    uint16_t n;
    uint16_t li;
    uint16_t hi;

    while (*gbk != '\0')
    {
        if (*gbk <= '~')
        {
            *utf8 = *gbk;
            gbk++;
            utf8++;
        }
        else
        {

            gbk_val.buf[0] = gbk[1];
            gbk_val.buf[1] = gbk[0];

#ifdef DEBUG
            printf("\r\n[%s][%s][%04u]gbk_val.val = 0x%X",
                   __FILE__, __func__, __LINE__, gbk_val.val);
#endif /* DEBUG */

            hi = 21946 - 1;

            li = 0;

            for (n = 16; n; n--)
            {
                i = li + (hi - li) / 2;

#ifdef DEBUG
                printf("\r\n[%s][%s][%04u]n = %d",
                       __FILE__, __func__, __LINE__, n);
                printf("\r\n[%s][%s][%04u]i = %d",
                       __FILE__, __func__, __LINE__, i);
                printf("\r\n[%s][%s][%04u]gbk2utf8_table[i].gbk = 0x%04X",
                       __FILE__, __func__, __LINE__, gbk2utf8_table[i].gbk);
#endif /* DEBUG */

                if (gbk_val.val == gbk2utf8_table[i].gbk)
                {
#ifdef DEBUG
                    printf("\r\n[%s][%s][%04u]’“µΩ",
                           __FILE__, __func__, __LINE__);
#endif /* DEBUG */
                    break;
                }
                if (gbk_val.val > gbk2utf8_table[i].gbk)
                {
                    li = i;
                }
                else
                {
                    hi = i;
                }
            }
            if (n != 0)
            {
                utf8_val.val = gbk2utf8_table[i].utf8;
                utf8[0] = utf8_val.buf[2];
                utf8[1] = utf8_val.buf[1];
                utf8[2] = utf8_val.buf[0];
            }

            // uint16_t i;
            // for (i = 0; i < 21793; i++)
            // {
            //     if (gbk2utf8_table[i].gbk == gbk_val.val)
            //     {
            //         utf8_val.val = gbk2utf8_table[i].utf8;

            //         utf8[0] = utf8_val.buf[2];
            //         utf8[1] = utf8_val.buf[1];
            //         utf8[2] = utf8_val.buf[0];

            //         break;
            //     }
            // }

//#ifdef DEBUG
//            printf("\r\n[%s][%s][%04u]gbk_val.val = 0x%04X utf8_val.val = 0x%X",
//                   __FILE__, __func__, __LINE__, gbk_val.val, utf8_val.val);
//#endif /* DEBUG */

            gbk += 2;
            utf8 += 3;
        }
    }
    *utf8 = '\0';
}

